/**
 * Orthographic ё→е twins plus extra full answers (word order, natural equivalents).
 * Case and punctuation are folded by the grader; gender stays locked in the key.
 */
function pack(
  answer: string,
  extra: string[] = [],
): { answer: string; acceptableAnswers?: string[] } {
  const bag: string[] = [];
  const seen = new Set<string>();
  const push = (s: string) => {
    const t = s.trim();
    if (!t || t === answer || seen.has(t)) return;
    seen.add(t);
    bag.push(t);
  };
  const expand = (s: string) => {
    push(s);
    const ye = s.replace(/ё/g, "е").replace(/Ё/g, "Е");
    if (ye !== s) push(ye);
  };
  expand(answer);
  for (const item of extra) expand(item);
  return bag.length ? { answer, acceptableAnswers: bag } : { answer };
}

